/**
 * The night sky behind the page.
 *
 * Real constellations (data/sky.json, generated by scripts/constellations.py) drift slowly across a
 * wrapping sky, with faint dust stars, a cursor that links to stars within reach, a hold-to-pull
 * gravity well, occasional shooting stars, and a hyperspace intro on load.
 */

const CURSOR_R = 130;     // stars inside this radius lean away from the cursor
const CURSOR_LINK = 120;  // the cursor draws a line to stars inside this radius
const INK = '236,233,227';
const HOT = '255,246,236';

const rnd = (a, b) => a + Math.random() * (b - a);
const clamp01 = (v) => Math.max(0, Math.min(1, v));
const easeOut = (v) => 1 - Math.pow(1 - v, 3);
const wrap = (v, n) => ((v % n) + n) % n;
const starRadius = (mag) => Math.max(0.7, Math.min(2.9, 2.45 - mag * 0.42));

/** Each constellation is {n: name, s: [[x, y, magnitude], ...], e: [[i, j], ...]}, x/y in degrees. */
export async function loadConstellations(url) {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`${url}: HTTP ${res.status}`);
  return res.json();
}

function readAccentRgb() {
  const raw = getComputedStyle(document.documentElement).getPropertyValue('--pk-accent-rgb');
  const parts = raw.split(',').map((s) => parseInt(s, 10));
  return parts.length === 3 && parts.every(Number.isFinite) ? parts.join(',') : '246,160,107';
}

export function createSky(canvas, { particleCount = 46, gravityWell = true, intro = true, hint = null } = {}) {
  const ctx = canvas.getContext('2d');
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const AC = readAccentRgb();
  const accent = (a) => `rgba(${AC},${a})`;
  const ink = (a) => `rgba(${INK},${a})`;
  const hot = (a) => `rgba(${HOT},${a})`;
  const dpr = Math.min(window.devicePixelRatio || 1, 2);

  let w = 0, h = 0, laidW = 0, laidH = 0;
  let constellations = [];
  let groups = [], dust = [], VW = 0, VH = 0;
  const drift = { x: 0, y: 0 };

  // Scale each figure to the viewport, then scatter them over a wrapping sky big enough that they never crowd.
  const layoutGroups = () => {
    groups = [];
    if (!constellations.length || !w || !h) return;
    const base = Math.max(120, Math.min(235, Math.min(w, h) * 0.25));
    const order = constellations.map((_, i) => i).sort(() => Math.random() - 0.5);
    groups = order.map((ci) => {
      const c = constellations[ci];
      const xs = c.s.map((p) => p[0]), ys = c.s.map((p) => p[1]);
      const ext = Math.max(Math.max(...xs) - Math.min(...xs), Math.max(...ys) - Math.min(...ys)) || 1;
      const k = (base * Math.max(0.5, Math.min(1.1, ext / 30))) / ext;
      const stars = c.s.map(([x, y, mag]) => ({
        rx: x * k, ry: y * k, mag, r: starRadius(mag),
        tw: rnd(0.5, 1.6), ph: rnd(0, Math.PI * 2), ox: 0, oy: 0, x: 0, y: 0, glow: 0,
      }));
      return {
        label: c.n.split('').join(' '), e: c.e, stars,
        R: Math.max(...stars.map((s) => Math.hypot(s.rx, s.ry))) + 14,
        ylo: Math.max(...stars.map((s) => s.ry)),
        gx: 0, gy: 0, x: 0, y: 0, lit: 0,
      };
    });
    const need = groups.reduce((t, g) => t + Math.pow(2 * g.R + 60, 2), 0) * 1.15;
    const maxR = Math.max(...groups.map((g) => g.R));
    const sc = Math.sqrt(need / (w * h));
    VW = Math.max(w * sc, w + 2 * maxR + 120);
    VH = Math.max(h * sc, h + 2 * maxR + 120);
    const placed = [];
    for (const g of groups) {
      let gx = 0, gy = 0, gap = 70;
      for (let t = 0; t < 900; t++) {
        if (t > 0 && t % 300 === 0) gap *= 0.5;
        gx = Math.random() * VW; gy = Math.random() * VH;
        const clear = placed.every((p) => {
          let dx = Math.abs(p.x - gx), dy = Math.abs(p.y - gy);
          dx = Math.min(dx, VW - dx); dy = Math.min(dy, VH - dy);
          return Math.hypot(dx, dy) > p.R + g.R + gap;
        });
        if (clear) break;
      }
      placed.push({ x: gx, y: gy, R: g.R });
      g.gx = gx; g.gy = gy;
    }
  };

  const layoutDust = () => {
    dust = [];
    for (let i = 0; i < particleCount; i++) {
      const mag = rnd(3.8, 5.6);
      dust.push({ bx: Math.random() * w, by: Math.random() * h, mag, r: starRadius(mag),
        tw: rnd(0.5, 1.6), ph: rnd(0, Math.PI * 2), ox: 0, oy: 0, x: 0, y: 0, glow: 0 });
    }
  };

  const resize = () => {
    w = canvas.clientWidth; h = canvas.clientHeight;
    canvas.width = w * dpr; canvas.height = h * dpr;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    // Mobile toolbars nudge the height while scrolling; only reshuffle the sky for a real resize.
    if (w !== laidW || Math.abs(h - laidH) > 150) {
      laidW = w; laidH = h;
      layoutGroups();
      layoutDust();
    }
  };
  resize();

  // ── pointer: cursor reticle, and the gravity well (a black hole) (hold to pull the stars in, let go to fling them out)
  const m = { x: -9999, y: -9999, down: false, charge: 0, t0: 0 };
  let holdT = 0, burst = null, lastAll = [];
  // other parts of the page can feel the well too: 'hold' when it starts, 'release' (with its charge) when it lets go
  const wellListeners = new Set();
  const emitWell = (type, detail) => { for (const fn of wellListeners) fn(type, detail); };
  const onMove = (e) => { if (e.pointerType !== 'touch') { m.x = e.clientX; m.y = e.clientY; } };
  const onLeave = () => { if (!m.down) { m.x = -9999; m.y = -9999; } };
  const onDown = (e) => {
    if (!gravityWell || reduce) return;
    if (e.pointerType === 'touch' || e.button !== 0) return;
    if (e.target.closest?.('a,button,summary,input,textarea,select,label,[contenteditable],dialog')) return;  // nor inside a project dialog
    m.down = true; m.t0 = performance.now(); m.charge = 0; m.x = e.clientX; m.y = e.clientY;
    document.body.style.userSelect = 'none';
    if (hint) hint.style.opacity = '0';
    emitWell('hold', { x: m.x, y: m.y });
  };
  const onUp = () => {
    if (!m.down) return;
    m.down = false;
    document.body.style.userSelect = '';
    const c = Math.max(0.15, m.charge), RG = 200 + 160 * c;
    for (const st of lastAll) {
      const dx = st.x - m.x, dy = st.y - m.y, d = Math.hypot(dx, dy);
      if (d < RG && d > 0.01) { const push = (1 - d / RG) * 120 * c + 12 * c; st.ox += dx / d * push; st.oy += dy / d * push; }
    }
    burst = { x: m.x, y: m.y, t0: performance.now(), c };
    emitWell('release', { x: m.x, y: m.y, c });
  };
  window.addEventListener('pointermove', onMove, { passive: true });
  document.documentElement.addEventListener('mouseleave', onLeave);
  window.addEventListener('resize', resize);
  window.addEventListener('pointerdown', onDown);
  window.addEventListener('pointerup', onUp);
  window.addEventListener('blur', onUp);

  const t0 = performance.now();
  let reticle = true;  // the drawn reticle under the pointer; off once the spacecraft cursor (ship-cursor.js) takes over

  // The gravity well, seen as a black hole: a dark shadow hugged by a thin ring of light, inside a tilted, swirling
  // accretion disk that burns brighter on the side turning toward us. The disk's far side is bent up over the top of
  // the shadow by the hole's gravity. It opens quickly, then grows as the hold charges. A warm haze around it goes on
  // the sky; the hole itself goes on the hole layer when there is one (ship-cursor.js puts one above the page, so
  // the sun or a headline can't hide it), otherwise on the sky too.
  let hole = null;  // { canvas, ctx, size } of the layer above the page
  let holeDrawn = false;
  const HOLE_SIZE = 200;  // CSS px; the disk at full charge is about 120 across
  const drawHaze = (now) => {
    const c = m.charge, open = 1 - Math.pow(1 - Math.min(1, holdT / 0.22), 3);
    const R = (6 + 12 * c) * open, haze = (70 + 100 * c) * open;
    const gl = ctx.createRadialGradient(m.x, m.y, R, m.x, m.y, haze);
    gl.addColorStop(0, accent(0.2 + 0.22 * c)); gl.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = gl; ctx.beginPath(); ctx.arc(m.x, m.y, haze, 0, Math.PI * 2); ctx.fill();
  };
  const drawHole = (g, x, y, now) => {
    const c = m.charge, ts = now * 0.001, TAU = Math.PI * 2;
    const open = 1 - Math.pow(1 - Math.min(1, holdT / 0.22), 3);
    const R = (6 + 12 * c) * open;                // the shadow's radius
    if (R < 0.5) return;
    const TILT = -0.28, FLAT = 0.24;              // the disk's tilt, and how nearly edge on it is seen
    const beam = g.createLinearGradient(x - R * 4, y, x + R * 4, y);
    beam.addColorStop(0, hot(0.95)); beam.addColorStop(0.5, accent(0.8)); beam.addColorStop(1, accent(0.42));
    // one half of the disk: the far half goes behind the shadow, the near half across the front of it
    const disk = (near) => {
      g.save();
      g.strokeStyle = beam; g.lineCap = 'round';
      for (let i = 0; i < 4; i++) {
        const r = R * (1.6 + i * 0.52);
        g.globalAlpha = 0.95 - i * 0.2;
        g.lineWidth = Math.max(0.6, (2.4 - i * 0.45) * (0.7 + 0.5 * c));
        g.setLineDash([r * 1.3, r * 0.22]); g.lineDashOffset = -ts * (150 / (i + 1));
        g.beginPath(); g.ellipse(x, y, r, r * FLAT, TILT, near ? 0 : Math.PI, near ? Math.PI : TAU); g.stroke();
      }
      g.restore();
    };
    disk(false);
    g.beginPath(); g.arc(x, y, R, 0, TAU); g.fillStyle = '#02040b'; g.fill();
    g.beginPath(); g.arc(x, y, R * 1.08, 0, TAU); g.strokeStyle = hot(0.8); g.lineWidth = 1; g.stroke();
    // the far side of the disk, lensed up over the top of the shadow and, faintly, under it
    g.save(); g.translate(x, y); g.rotate(TILT);
    g.lineCap = 'round';
    g.strokeStyle = accent(0.22); g.lineWidth = 5 + 4 * c;
    g.beginPath(); g.ellipse(0, 0, R * 1.5, R * 1.32, 0, Math.PI * 1.06, Math.PI * 1.94); g.stroke();
    g.strokeStyle = hot(0.8); g.lineWidth = 1.4 + 1.2 * c;
    g.beginPath(); g.ellipse(0, 0, R * 1.5, R * 1.32, 0, Math.PI * 1.06, Math.PI * 1.94); g.stroke();
    g.strokeStyle = accent(0.4); g.lineWidth = 1;
    g.beginPath(); g.ellipse(0, 0, R * 1.36, R * 1.18, 0, Math.PI * 0.14, Math.PI * 0.86); g.stroke();
    g.restore();
    disk(true);
  };
  const drawWell = (now) => {
    if (!m.down) {
      if (hole && holeDrawn) { hole.ctx.clearRect(0, 0, HOLE_SIZE, HOLE_SIZE); holeDrawn = false; }
      return false;
    }
    drawHaze(now);
    if (hole) {
      hole.ctx.clearRect(0, 0, HOLE_SIZE, HOLE_SIZE);
      drawHole(hole.ctx, HOLE_SIZE / 2, HOLE_SIZE / 2, now);
      holeDrawn = true;
    } else drawHole(ctx, m.x, m.y, now);
    return true;
  };

  const drawCursor = (now) => {
    if (m.x < -1000) return;
    if (drawWell(now)) return;
    if (!reticle) return;
    const el = ((now - t0) % 2600) / 2600;
    for (const off of [0, 0.5]) {
      const k = (el + off) % 1;
      ctx.beginPath(); ctx.arc(m.x, m.y, 10 + k * 44, 0, Math.PI * 2);
      ctx.strokeStyle = accent(0.34 * (1 - k)); ctx.lineWidth = 1; ctx.stroke();
    }
    ctx.beginPath(); ctx.arc(m.x, m.y, 3, 0, Math.PI * 2);
    ctx.fillStyle = accent(0.85); ctx.fill();
    ctx.save();
    ctx.setLineDash([3, 4]);
    ctx.strokeStyle = accent(0.16);
    ctx.beginPath(); ctx.moveTo(m.x - 26, m.y); ctx.lineTo(m.x + 26, m.y);
    ctx.moveTo(m.x, m.y - 26); ctx.lineTo(m.x, m.y + 26); ctx.stroke();
    ctx.restore();
  };

  // Ease a star toward its resting place, nudged by the cursor or spiralled in by the gravity well.
  const settle = (st, bx, by) => {
    const dx = bx - m.x, dy = by - m.y, d = Math.hypot(dx, dy);
    let tx = 0, ty = 0, ease = 0.08;
    if (m.down) {
      const RG = 200 + 160 * m.charge;
      if (d < RG && d > 0.01) {
        const f = 1 - d / RG;
        const r2 = d - Math.min(d * 0.86, (70 + 170 * m.charge) * f);
        const ang = Math.atan2(dy, dx) + f * f * holdT * (0.9 + 1.6 * m.charge);
        tx = m.x + Math.cos(ang) * r2 - bx; ty = m.y + Math.sin(ang) * r2 - by;
        ease = 0.1;
      }
    } else if (d < CURSOR_R && d > 0.01) {
      const f = (1 - d / CURSOR_R) * 16; tx = (dx / d) * f; ty = (dy / d) * f;
    }
    st.ox += (tx - st.ox) * ease; st.oy += (ty - st.oy) * ease;
    st.x = bx + st.ox; st.y = by + st.oy;
  };

  const meteors = [];
  let nextMeteor = performance.now() + rnd(2500, 6000);

  // ── hyperspace intro: stars streak past, then the sky drops out of warp into the constellations
  let introPending = intro, introState = null, introSafety = 0;
  const warp = [];
  const spawnWarp = (fresh) => ({ a: rnd(0, Math.PI * 2), d: fresh ? rnd(1, Math.max(w, h) * 0.45) : rnd(1, 24), z: rnd(0.5, 1.3) });
  const startIntro = (now) => {
    introState = { t0: now, hidden: true };
    warp.length = 0;
    for (let i = 0; i < 340; i++) warp.push(spawnWarp(true));
    document.documentElement.setAttribute('data-pk-intro', '');
    clearTimeout(introSafety);
    introSafety = setTimeout(() => document.documentElement.removeAttribute('data-pk-intro'), 3200);
  };
  const drawWarp = (iT) => {
    const cx = w / 2, cy = h * 0.46, maxD = Math.hypot(w, h) * 0.6;
    const sp = iT < 0.3 ? (iT / 0.3) * 0.25 : iT < 1.15 ? 0.25 + (iT - 0.3) * 2.2 : Math.max(0, 2.12 * (1 - (iT - 1.15) / 0.55));
    const fade = 1 - clamp01((iT - 1.2) / 0.6);
    if (fade > 0) {
      ctx.lineCap = 'round';
      for (const p of warp) {
        const v = (1.5 + p.d * 0.055) * sp * p.z;
        p.d += v;
        if (p.d > maxD) { if (iT < 1.15) Object.assign(p, spawnWarp(false)); continue; }
        const tail = Math.max(1.5, v * 2.4);
        const c = Math.cos(p.a), s = Math.sin(p.a);
        const a = Math.min(1, p.d / (Math.min(w, h) * 0.18)) * fade * (0.35 + 0.5 * p.z);
        ctx.strokeStyle = p.z > 1.05 ? accent(a) : ink(a);
        ctx.lineWidth = 0.6 + p.z * 0.9;
        ctx.beginPath(); ctx.moveTo(cx + c * (p.d - tail), cy + s * (p.d - tail)); ctx.lineTo(cx + c * p.d, cy + s * p.d); ctx.stroke();
      }
      ctx.lineCap = 'butt';
    }
    const flash = Math.max(0, 1 - Math.abs(iT - 1.2) / 0.35);
    if (flash > 0) {
      const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, Math.max(w, h) * 0.7);
      g.addColorStop(0, hot(0.32 * flash)); g.addColorStop(0.4, accent(0.10 * flash)); g.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = g; ctx.fillRect(0, 0, w, h);
    }
  };

  const drawMeteors = (now) => {
    if (!reduce && !introState && now > nextMeteor) {
      const a = rnd(2.55, 2.85), sp = rnd(9, 14);
      meteors.push({ x: rnd(w * 0.3, w * 1.05), y: rnd(-30, h * 0.4), dx: Math.cos(a) * sp, dy: Math.sin(a) * sp,
        len: rnd(110, 210), age: 0, life: rnd(42, 62) });
      nextMeteor = now + rnd(5000, 11000);
    }
    for (let i = meteors.length - 1; i >= 0; i--) {
      const mt = meteors[i];
      mt.age++; mt.x += mt.dx; mt.y += mt.dy;
      const k = mt.age / mt.life;
      if (k >= 1) { meteors.splice(i, 1); continue; }
      const fade = Math.sin(Math.PI * k);
      const sp = Math.hypot(mt.dx, mt.dy);
      const tx = mt.x - (mt.dx / sp) * mt.len, ty = mt.y - (mt.dy / sp) * mt.len;
      const gr = ctx.createLinearGradient(mt.x, mt.y, tx, ty);
      gr.addColorStop(0, hot(0.85 * fade)); gr.addColorStop(0.25, accent(0.35 * fade)); gr.addColorStop(1, accent(0));
      ctx.strokeStyle = gr; ctx.lineWidth = 1.3;
      ctx.beginPath(); ctx.moveTo(mt.x, mt.y); ctx.lineTo(tx, ty); ctx.stroke();
      ctx.beginPath(); ctx.arc(mt.x, mt.y, 1.6, 0, Math.PI * 2);
      ctx.fillStyle = hot(fade); ctx.fill();
    }
  };

  const drawBurst = (now) => {
    if (!burst) return;
    // the frame's timestamp can be a few ms older than the pointerup that set t0, so clamp at 0
    const e = Math.max(0, (now - burst.t0) / 750);
    if (e >= 1) { burst = null; return; }
    const ee = 1 - Math.pow(1 - e, 3);
    ctx.beginPath(); ctx.arc(burst.x, burst.y, 12 + 420 * ee * (0.6 + 0.4 * burst.c), 0, Math.PI * 2);
    ctx.strokeStyle = hot((1 - e) * 0.55); ctx.lineWidth = 2.2 * (1 - e) + 0.4; ctx.stroke();
    ctx.beginPath(); ctx.arc(burst.x, burst.y, 8 + 260 * ee, 0, Math.PI * 2);
    ctx.strokeStyle = accent((1 - e) * 0.5); ctx.lineWidth = 1; ctx.stroke();
    const fg = ctx.createRadialGradient(burst.x, burst.y, 0, burst.x, burst.y, 160);
    fg.addColorStop(0, hot(0.5 * Math.pow(1 - e, 2) * burst.c)); fg.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = fg; ctx.fillRect(burst.x - 160, burst.y - 160, 320, 320);
  };

  const draw = (now = performance.now()) => {
    const tsec = now * 0.001;
    ctx.clearRect(0, 0, w, h);
    if (introPending) { introPending = false; if (!reduce) startIntro(now); }
    const iT = introState ? (now - introState.t0) / 1000 : 99;
    const ik = introState ? easeOut(clamp01((iT - 1.15) / 1.2)) : 1;
    if (introState && introState.hidden && iT > 1.5) { introState.hidden = false; document.documentElement.removeAttribute('data-pk-intro'); }
    if (m.down) { holdT = Math.max(0, (now - m.t0) / 1000); m.charge = Math.min(1, holdT / 1.6); }
    // the whole sky turns slowly, like the night sky does
    if (!reduce) { drift.x -= 0.11; drift.y += 0.018; }
    const sy = window.scrollY || document.documentElement.scrollTop || 0;
    const twinkle = (st) => (reduce ? 1 : 0.7 + 0.3 * Math.sin(tsec * st.tw + st.ph));
    const all = [];
    ctx.font = '9.5px "JetBrains Mono", monospace';
    ctx.textAlign = 'center';
    ctx.save();
    if (ik < 1) {
      const cx = w / 2, cy = h * 0.46, sc = 0.15 + 0.85 * ik;
      ctx.globalAlpha = ik;
      ctx.translate(cx, cy); ctx.scale(sc, sc); ctx.translate(-cx, -cy);
    }

    for (const g of groups) {
      g.x = wrap(g.gx + drift.x, VW) - (VW - w) / 2;
      g.y = wrap(g.gy + drift.y - sy * 0.12, VH) - (VH - h) / 2;
      if (g.x < -g.R - 40 || g.x > w + g.R + 40 || g.y < -g.R - 40 || g.y > h + g.R + 40) { g.lit = 0; continue; }
      let near = Infinity;
      for (const st of g.stars) {
        settle(st, g.x + st.rx, g.y + st.ry);
        near = Math.min(near, Math.hypot(st.x - m.x, st.y - m.y));
        all.push(st);
      }
      const over = Math.hypot(g.x - m.x, g.y - m.y) < g.R * 0.85 || near < 60;
      g.lit += ((over ? 1 : 0) - g.lit) * 0.07;
      const lit = g.lit > 0.02;
      ctx.lineWidth = 1;
      ctx.strokeStyle = lit ? accent(0.12 + g.lit * 0.32) : ink(0.12);
      ctx.beginPath();
      for (const [i, j] of g.e) { ctx.moveTo(g.stars[i].x, g.stars[i].y); ctx.lineTo(g.stars[j].x, g.stars[j].y); }
      ctx.stroke();
      ctx.fillStyle = lit ? accent(0.16 + g.lit * 0.5) : ink(0.14);
      ctx.fillText(g.label, g.x, g.y + g.ylo + 22);
    }
    for (const st of dust) {
      if (!reduce) { st.bx -= 0.055; st.by += 0.009; }
      if (st.bx < -20) st.bx = w + 20; if (st.bx > w + 20) st.bx = -20;
      if (st.by < -20) st.by = h + 20; if (st.by > h + 20) st.by = -20;
      settle(st, st.bx, wrap(st.by - sy * 0.05 + 20, h + 40) - 20);
      all.push(st);
    }

    // the cursor joins any star within reach
    if (ik >= 1) for (const st of all) {
      const d = Math.hypot(st.x - m.x, st.y - m.y);
      const k = d < CURSOR_LINK ? 1 - d / CURSOR_LINK : 0;
      st.glow += (k - st.glow) * 0.15;
      if (k > 0) {
        ctx.strokeStyle = accent(k * 0.36); ctx.lineWidth = 1;
        ctx.beginPath(); ctx.moveTo(st.x, st.y); ctx.lineTo(m.x, m.y); ctx.stroke();
      }
    }
    for (const st of all) {
      const tw = twinkle(st);
      const r = st.r * (1 + st.glow * 0.35);
      const lit = st.glow > 0.02;
      if (st.mag < 2.1) {
        ctx.beginPath(); ctx.arc(st.x, st.y, r * 3.4, 0, Math.PI * 2);
        ctx.fillStyle = lit ? accent(0.05 + st.glow * 0.10) : ink(0.05 * tw);
        ctx.fill();
      }
      const base = Math.max(0.2, Math.min(0.75, 0.82 - st.mag * 0.13));
      ctx.beginPath(); ctx.arc(st.x, st.y, r, 0, Math.PI * 2);
      ctx.fillStyle = lit ? accent(0.35 + st.glow * 0.6) : ink(base * tw);
      ctx.fill();
    }
    ctx.restore();
    lastAll = all;

    if (introState) { drawWarp(iT); if (iT > 2.6) introState = null; }
    drawMeteors(now);
    if (ik >= 1) drawCursor(now);
    drawBurst(now);
    requestAnimationFrame(draw);
  };
  draw();

  return {
    setConstellations(data) { constellations = Array.isArray(data) ? data : []; layoutGroups(); },
    replayIntro() { window.scrollTo(0, 0); introPending = true; },
    // the gravity well right now: where it is (viewport px), whether it's held, and its charge (0 to 1 over 1.6 s)
    well() { return { down: m.down, x: m.x, y: m.y, charge: m.charge }; },
    onWell(fn) { wellListeners.add(fn); return () => wellListeners.delete(fn); },
    // the drawn reticle under the pointer, for when something else is the cursor
    setReticle(on) { reticle = !!on; },
    // a canvas that rides with the pointer above the page, HOLE_SIZE square and centred on it, for the black hole
    setHoleLayer(layer) {
      if (!layer) { hole = null; return; }
      layer.width = HOLE_SIZE * dpr; layer.height = HOLE_SIZE * dpr;
      const g = layer.getContext('2d'); g.setTransform(dpr, 0, 0, dpr, 0, 0);
      hole = { canvas: layer, ctx: g };
    },
  };
}
